/// <summary>
///     The <c>AVABPCleanUpContract</c> class is the data contract class for <c>BP-CleanUps</c>
/// </summary>
[
    DataContractAttribute,
    SysOperationContractProcessingAttribute(classStr(AVABPCleanUpUIBuilder)),
    SysOperationGroupAttribute('BuildingProject',   literalStr("@SYP4910021"),                  '2') // , FormArrangeMethod::Vertical),
]
class AVABPCleanUpContract implements   SysOperationValidatable,
                                        SysOperationInitializable
{
    Args                        args;

    AVABPOlderThanNumberOfDays  avaBPOlderThanNumberOfDays;
    AVABPDateTimeOlderThan      avaBPDateTimeOlderThan;

}

