/// <summary>
///    AVA <c>initialize</c> method.
/// </summary>
public void initialize()
{
    avaBPOlderThanNumberOfDays  = 30;

    avaBPDateTimeOlderThan      =  DateTimeUtil::addDays(DateTimeUtil::newDateTime(DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()), 0), -avaBPOlderThanNumberOfDays);
}

